@using sv_ad91cc2b22b64aee8d6a34a82d6fd54b.Models

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var cssClass = GetStepClass(stepIndex);
            <li class="step-item @cssClass"
                @onclick="() => HandleStepClick(stepIndex)"
                role="button"
                aria-current="@(stepIndex == CurrentStep ? "step" : null)">
                <span class="step-number">
                    @if (CompletedSteps.Contains(stepIndex))
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
            @if (i < StepNames.Length - 1)
            {
                <li class="step-connector" aria-hidden="true"></li>
            }
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "dimmed";
    }

    private async Task HandleStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

@using sv_ad91cc2b22b64aee8d6a34a82d6fd54b.Models

<div class="form-step">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="Model.FullName" @bind:event="oninput" placeholder="Enter your full name" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Model.Email" @bind:event="oninput" placeholder="Enter your email" />
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Model.Phone" @bind:event="oninput" placeholder="Enter your phone number" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" @bind="Model.Address" @bind:event="oninput" placeholder="Enter your address" rows="3"></textarea>
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName))
        {
            ErrorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Email))
        {
            ErrorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            ErrorMessage = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Address))
        {
            ErrorMessage = "Address is required.";
            return;
        }

        IsValidating = true;
        try
        {
            var isEmailValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!isEmailValid)
            {
                ErrorMessage = "The email address is not valid. Please enter a valid email.";
                return;
            }
        }
        finally
        {
            IsValidating = false;
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_ad91cc2b22b64aee8d6a34a82d6fd54b.Models

<div class="form-step">
    <h3>Work History</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        var entry = Entries[index];
        <fieldset class="work-entry">
            <legend>Position @(index + 1)</legend>

            @if (Entries.Count > 1)
            {
                <button class="btn-remove" @onclick="() => RemoveEntry(index)" type="button">Remove</button>
            }

            <div class="form-group">
                <label>Company Name *</label>
                <input type="text" @bind="entry.Company" @bind:event="oninput" placeholder="Company name" />
            </div>

            <div class="form-group">
                <label>Job Title *</label>
                <input type="text" @bind="entry.Title" @bind:event="oninput" placeholder="Job title" />
            </div>

            <div class="form-row">
                <div class="form-group">
                    <label>Start Date *</label>
                    <input type="date" @bind="entry.StartDate" />
                </div>

                <div class="form-group">
                    <label>
                        <input type="checkbox" @bind="entry.IsCurrent" /> Currently working here
                    </label>
                </div>

                @if (!entry.IsCurrent)
                {
                    <div class="form-group">
                        <label>End Date</label>
                        <input type="date" @bind="entry.EndDate" />
                    </div>
                }
            </div>

            <div class="form-group">
                <label>Description</label>
                <textarea @bind="entry.Description" @bind:event="oninput" placeholder="Describe your responsibilities" rows="3"></textarea>
            </div>
        </fieldset>
    }

    <button class="btn-secondary" @onclick="AddEntry" type="button">+ Add Another Position</button>

    <div class="form-actions">
        <button class="btn-secondary" @onclick="OnBack" type="button">Back</button>
        <button class="btn-primary" @onclick="HandleNext" type="button">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position must have a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_ad91cc2b22b64aee8d6a34a82d6fd54b.Models

<div class="form-step">
    <h3>References</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];
        <fieldset class="reference-entry">
            <legend>Reference @(index + 1)</legend>

            @if (References.Count > 2)
            {
                <button class="btn-remove" @onclick="() => RemoveReference(index)" type="button">Remove</button>
            }

            <div class="form-group">
                <label>Name *</label>
                <input type="text" @bind="reference.Name" @bind:event="oninput" placeholder="Reference name" />
            </div>

            <div class="form-group">
                <label>Relationship *</label>
                <input type="text" @bind="reference.Relationship" @bind:event="oninput" placeholder="e.g., Former Manager" />
            </div>

            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" @bind="reference.Email" @bind:event="oninput" placeholder="Email" />
                </div>

                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" @bind="reference.Phone" @bind:event="oninput" placeholder="Phone" />
                </div>
            </div>
        </fieldset>
    }

    @if (References.Count < 3)
    {
        <button class="btn-secondary" @onclick="AddReference" type="button">+ Add Reference</button>
    }

    <div class="form-actions">
        <button class="btn-secondary" @onclick="OnBack" type="button">Back</button>
        <button class="btn-primary" @onclick="HandleNext" type="button">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_ad91cc2b22b64aee8d6a34a82d6fd54b.Models

<div class="form-step">
    <h3>Cover Letter</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter"
                  @bind="CoverLetterText"
                  @bind:event="oninput"
                  placeholder="Tell us why you're a great fit for this position..."
                  rows="12"
                  maxlength="@MaxLength"></textarea>
        <div class="char-count">@CoverLetterText.Length / @MaxLength characters</div>
    </div>

    <div class="form-actions">
        <button class="btn-secondary" @onclick="OnBack" type="button">Back</button>
        <button class="btn-primary" @onclick="HandleNext" type="button">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter, EditorRequired] public string CoverLetterText { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> CoverLetterTextChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetterText))
        {
            ErrorMessage = "Please write a cover letter.";
            return;
        }

        await CoverLetterTextChanged.InvokeAsync(CoverLetterText);
        await OnNext.InvokeAsync();
    }
}

@using sv_ad91cc2b22b64aee8d6a34a82d6fd54b.Models

<div class="form-step">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <h4>&#10003; Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="validation-error" role="alert">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-header">
                <h4>Personal Information</h4>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Model.Personal.FullName</dd>
                <dt>Email</dt><dd>@Model.Personal.Email</dd>
                <dt>Phone</dt><dd>@Model.Personal.Phone</dd>
                <dt>Address</dt><dd>@Model.Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h4>Work History</h4>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in Model.WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <br />
                    <span>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h4>References</h4>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in Model.References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />
                    <span>@r.Email &bull; @r.Phone</span>
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h4>Cover Letter</h4>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@Model.CoverLetter</p>
        </section>

        <div class="form-actions">
            <button class="btn-secondary" @onclick="OnBack" type="button">Back</button>
            <button class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting" type="button">
                @if (IsSubmitting)
                {
                    <span>Submitting...</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public ApplicationFormModel Model { get; set; } = default!;
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int? ApplicationId;
    private string? ErrorMessage;

    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private async Task HandleSubmit()
    {
        ErrorMessage = null;
        IsSubmitting = true;

        try
        {
            var application = Model.ToRecord();
            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

