toolArgs.file_text:
@using sv_ad91cc2b22b64aee8d6a34a82d6fd54b.Models

<div class="form-step">
    <h3>Work History</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        var entry = Entries[index];
        <fieldset class="work-entry">
            <legend>Position @(index + 1)</legend>

            @if (Entries.Count > 1)
            {
                <button class="btn-remove" @onclick="() => RemoveEntry(index)" type="button">Remove</button>
            }

            <div class="form-group">
                <label>Company Name *</label>
                <input type="text" @bind="entry.Company" @bind:event="oninput" placeholder="Company name" />
            </div>

            <div class="form-group">
                <label>Job Title *</label>
                <input type="text" @bind="entry.Title" @bind:event="oninput" placeholder="Job title" />
            </div>

            <div class="form-row">
                <div class="form-group">
                    <label>Start Date *</label>
                    <input type="date" @bind="entry.StartDate" />
                </div>

                <div class="form-group">
                    <label>
                        <input type="checkbox" @bind="entry.IsCurrent" /> Currently working here
                    </label>
                </div>

                @if (!entry.IsCurrent)
                {
                    <div class="form-group">
                        <label>End Date</label>
                        <input type="date" @bind="entry.EndDate" />
                    </div>
                }
            </div>

            <div class="form-group">
                <label>Description</label>
                <textarea @bind="entry.Description" @bind:event="oninput" placeholder="Describe your responsibilities" rows="3"></textarea>
            </div>
        </fieldset>
    }

    <button class="btn-secondary" @onclick="AddEntry" type="button">+ Add Another Position</button>

    <div class="form-actions">
        <button class="btn-secondary" @onclick="OnBack" type="button">Back</button>
        <button class="btn-primary" @onclick="HandleNext" type="button">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position must have a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

