@using sv_ad91cc2b22b64aee8d6a34a82d6fd54b.Models

<div class="form-step">
    <h3>References</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];
        <fieldset class="reference-entry">
            <legend>Reference @(index + 1)</legend>

            @if (References.Count > 2)
            {
                <button class="btn-remove" @onclick="() => RemoveReference(index)" type="button">Remove</button>
            }

            <div class="form-group">
                <label>Name *</label>
                <input type="text" @bind="reference.Name" @bind:event="oninput" placeholder="Reference name" />
            </div>

            <div class="form-group">
                <label>Relationship *</label>
                <input type="text" @bind="reference.Relationship" @bind:event="oninput" placeholder="e.g., Former Manager" />
            </div>

            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" @bind="reference.Email" @bind:event="oninput" placeholder="Email" />
                </div>

                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" @bind="reference.Phone" @bind:event="oninput" placeholder="Phone" />
                </div>
            </div>
        </fieldset>
    }

    @if (References.Count < 3)
    {
        <button class="btn-secondary" @onclick="AddReference" type="button">+ Add Reference</button>
    }

    <div class="form-actions">
        <button class="btn-secondary" @onclick="OnBack" type="button">Back</button>
        <button class="btn-primary" @onclick="HandleNext" type="button">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

