arguments.file_text:
@page "/apply"
@using sv_ad91cc2b22b64aee8d6a34a82d6fd54b.Models
@using sv_ad91cc2b22b64aee8d6a34a82d6fd54b.Components.Pages.Apply
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@model.Personal"
                              ApplicationService="@ApplicationService"
                              OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="@model.WorkEntries"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="@model.References"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetterText="@model.CoverLetter"
                             CoverLetterTextChanged="UpdateCoverLetter"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Model="@model"
                        ApplicationService="@ApplicationService"
                        OnEditStep="GoToStep"
                        OnBack="PreviousStep"
                        OnSubmit="HandleSubmitted" />
            break;
    }
</div>

@code {
    private ApplicationFormModel model = new();
    private int currentStep = 0;
    private HashSet<int> completedSteps = new();

    private void NextStep()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void PreviousStep()
    {
        currentStep--;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void UpdateCoverLetter(string text)
    {
        model.CoverLetter = text;
    }

    private void HandleSubmitted()
    {
        // Mark all steps as completed
        for (int i = 0; i < 5; i++)
            completedSteps.Add(i);
    }
}

.application-form {
    max-width: 800px;
    margin: 2rem auto;
    padding: 1.5rem;
}

/* Step Indicator */
.step-list {
    display: flex;
    align-items: center;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem 0;
}

.step-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: default;
    padding: 0.5rem 0.75rem;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    white-space: nowrap;
}

.step-item.completed {
    cursor: pointer;
    color: #16a34a;
}

.step-item.active {
    background-color: #2563eb;
    color: white;
    font-weight: 600;
}

.step-item.dimmed {
    color: #9ca3af;
}

.step-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.75rem;
    height: 1.75rem;
    border-radius: 50%;
    border: 2px solid currentColor;
    font-size: 0.75rem;
    font-weight: 600;
}

.step-item.active .step-number {
    border-color: white;
    background-color: rgba(255, 255, 255, 0.2);
}

.checkmark {
    font-weight: bold;
}

.step-connector {
    flex: 1;
    height: 2px;
    background-color: #d1d5db;
    min-width: 1rem;
    list-style: none;
}

/* Form Step */
.form-step {
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

.form-step h3 {
    margin: 0 0 1.5rem 0;
    font-size: 1.25rem;
    color: #111827;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    font-size: 0.875rem;
    color: #374151;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.form-row .form-group {
    flex: 1;
    min-width: 150px;
}

.form-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #e5e7eb;
}

/* Buttons */
.btn-primary {
    background-color: #2563eb;
    color: white;
    border: none;
    padding: 0.625rem 1.5rem;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
}

.btn-primary:hover:not(:disabled) {
    background-color: #1d4ed8;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-secondary {
    background-color: #f3f4f6;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.625rem 1.5rem;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
}

.btn-secondary:hover {
    background-color: #e5e7eb;
}

.btn-remove {
    float: right;
    background: none;
    border: none;
    color: #dc2626;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.25rem 0.5rem;
}

.btn-remove:hover {
    text-decoration: underline;
}

.btn-link {
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

/* Work entry / reference fieldsets */
.work-entry,
.reference-entry {
    border: 1px solid #e5e7eb;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.work-entry legend,
.reference-entry legend {
    font-weight: 600;
    font-size: 0.875rem;
    color: #4b5563;
    padding: 0 0.5rem;
}

/* Validation */
.validation-error {
    background-color: #fef2f2;
    border: 1px solid #fecaca;
    color: #dc2626;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    font-size: 0.875rem;
}

/* Character count */
.char-count {
    text-align: right;
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

/* Review step */
.review-section {
    border: 1px solid #e5e7eb;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h4 {
    margin: 0;
    font-size: 1rem;
    color: #111827;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
    font-size: 0.875rem;
}

.review-section dt {
    font-weight: 600;
    color: #4b5563;
}

.review-section dd {
    margin: 0;
    color: #111827;
}

.review-work-entry,
.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f3f4f6;
    font-size: 0.875rem;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    font-size: 0.875rem;
    color: #374151;
    margin: 0;
}

/* Submission confirmation */
.submission-confirmation {
    text-align: center;
    padding: 2rem;
}

.submission-confirmation h4 {
    color: #16a34a;
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

